window.MG_LAZY_DATA["data/lazy/resources/hpc-v26-094-7f40a17fc8722614.json"]={sha256:"7f40a17fc87226140f8cca543edba9503507f7a978a0bac774e0ca400ec5fe20",value:{"sources":[{"id":"v26-case-3f4cb1b7ffa433f1","url":"https://www.energy.gov/sites/default/files/2024-07/best-practice-guide-data-center-design_0.pdf","title":"Best practices for energy-efficient data center design","titleEn":"Best practices for energy-efficient data center design","publisher":"US Department of Energy","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"hpc-v26-094","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"hpc-v26-094","related":[{"id":"hpc-v26-095","referenceUrls":["https://sci.greensoftware.foundation/"],"title":"SCI 軟體碳強度：能源、隱含碳與功能單位","titleEn":"Software Carbon Intensity: energy, embodied carbon and functional units","why":"用兩課的可觀察驗收條件比較模型邊界：節能聲明有共同基準，不拿不同負載直接比較。","whyEn":"Compare model boundaries using observable acceptance criteria: Energy claims use a common baseline rather than mismatched loads.","difference":"以合成資料重建「SCI 軟體碳強度：能源、隱含碳與功能單位」，能分離架構事實、模型假設與驗收證據。完成：交付SCI邊界、E/I/M/R帳本、兩情境與排程限制。","differenceEn":"Reconstruct Software Carbon Intensity: energy, embodied carbon and functional units with synthetic data; distinguish architecture facts, model assumptions and acceptance evidence. Complete: Deliver SCI boundaries, E/I/M/R ledgers, two scenarios and scheduling constraints.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["計算8760 MWh IT再乘1.5，分開設施額外量。","計100×400營運排放，加10000隱含碳，再除100完成job。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Compute 8760 MWh IT, multiply by 1.5 and isolate overhead.","Compute 100×400 operational emissions, add 10000 embodied emissions and divide by 100 completed jobs.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"hpc-v26-004","referenceUrls":["https://research.ibm.com/publications/overview-of-the-blue-genel-system-architecture"],"title":"Blue Gene/L：雙核心角色與虛擬節點取捨","titleEn":"Blue Gene/L: dual-core roles and virtual-node tradeoffs","why":"用兩課的可觀察驗收條件比較模型邊界：節能聲明有共同基準，不拿不同負載直接比較。","whyEn":"Compare model boundaries using observable acceptance criteria: Energy claims use a common baseline rather than mismatched loads.","difference":"畫兩核心的讀取、計算及等待區；把雙核心模式視為部署選項，不假設效能自動加倍；52、68、84與44門檻可重算，無重複或遺漏工作ID。","differenceEn":"Draw reads, computation and waits on both cores; treat modes as deployment choices rather than automatic doubling. Reproduce 52, 68, 84 and break-even 44 with no repeated or missing job IDs.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["計算8760 MWh IT再乘1.5，分開設施額外量。","教學方案A以兩核心分攤W並付同步h，T=W/2+h；方案B一核心計算、另一服務，T=W+c；固定W=80毫秒，方案A h=12；改h=28，資料及計算量不變。方案B c=4；名義式 80/2+12 = 52 ms；變更式 80/2+28 = 68 ms。數據與驗收門檻為原創教學情境，並非所列超級電腦或函式庫的實測規格。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Compute 8760 MWh IT, multiply by 1.5 and isolate overhead.","Teaching option A splits W across two cores plus synchronization h; option B uses one compute core and one service core, T=W+c. W=80 ms, option A h=12 then 28 with identical data/work; option B c=4. Nominal 80/2+12 = 52 ms; changed 80/2+28 = 68 ms. Inputs and acceptance thresholds are original teaching scenarios, not measured specifications of the named systems or libraries.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-6e6533381c9c96bf","url":"https://sci.greensoftware.foundation/","title":"Software Carbon Intensity specification","titleEn":"Software Carbon Intensity specification","publisher":"Green Software Foundation","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-1e61fd473c64b4f3","url":"https://research.ibm.com/publications/overview-of-the-blue-genel-system-architecture","title":"Overview of the Blue Gene/L system architecture","titleEn":"Overview of the Blue Gene/L system architecture","publisher":"IBM Research","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
